using System;using System.IO;using System.Linq;using System.Web.Script.Serialization;
internal static class UninstallStageTests {
 static int Main(){string folder=Path.Combine(Path.GetTempPath(),"HubUninstallTest-"+Guid.NewGuid().ToString("N").Substring(0,10)),root=Path.Combine(folder,"app with spaces"),temporary=Path.Combine(folder,"temporary");Directory.CreateDirectory(root);Directory.CreateDirectory(temporary);foreach(string name in new[]{"native-actions.ps1","native-lifecycle.ps1","service-removal.ps1","service-compatibility.ps1","service-compatibility.json","shortcuts.ps1","uninstall-data.ps1","upgrade.ps1","legacy-msi-products.json","legacy-managers.json","manifest.json"})File.WriteAllText(Path.Combine(root,name),"current inventory "+name);
 foreach(string path in new[]{"engine/scripts/common-windows.ps1","engine/assets/theme-runtime.mjs","engine/runtime/node/node.exe","source/assets/pets/precious.mp4","wallpapers/personal.mp4"}){string file=Path.Combine(root,path);Directory.CreateDirectory(Path.GetDirectoryName(file));File.WriteAllText(file,"keep "+path);}
 string stage=NativeUninstall.Prepare(root,temporary);if(File.ReadAllText(Path.Combine(stage,"manifest.json"))!="current inventory manifest.json"||!File.Exists(Path.Combine(stage,"engine/runtime/node/node.exe"))||Directory.Exists(Path.Combine(stage,"source"))||Directory.Exists(Path.Combine(stage,"wallpapers")))throw new Exception("Small uninstaller did not use the current inventory or copied wallpaper/pet materials");if(Directory.GetFiles(root,"*",SearchOption.AllDirectories).Length!=16)throw new Exception("Preparing uninstall modified the installed app");Console.WriteLine(new JavaScriptSerializer().Serialize(new{pass=true,currentInventory=true,offlineRuntimeCopied=true,wallpaperAndPetsNotCopied=true,installationUnchanged=true,fixture=folder}));return 0;}
}
